class Solution {
    public int[] dailyTemperatures(int[] temperatures) {
        int n = temperatures.length;
        int[] res = new int[n];

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (temperatures[j] > temperatures[i]) {   // 严格大于
                    res[i] = j - i;
                    break;
                }
            }
        }
        return res;
    }
}

class Solution {
    public int[] dailyTemperatures(int[] temperatures) {
        int n = temperatures.length;
        int[] res = new int[n];

        // 从右往左，右侧答案已经算好，可以按答案跳跃
        for (int i = n - 2; i >= 0; i--) {
            int j = i + 1;
            // 只要还不比今天热且还能继续跳，就按已算答案往前跳
            while (temperatures[j] <= temperatures[i] && res[j] != 0) {
                j += res[j];
            }
            if (temperatures[j] > temperatures[i]) {
                res[i] = j - i;
            }
        }
        return res;
    }
}

import java.util.*;

class Solution {
    public int[] dailyTemperatures(int[] temperatures) {
        int n = temperatures.length;
        int[] res = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();   // 存下标

        for (int i = 0; i < n; i++) {
            // 今天比栈顶那天热：栈顶那天的答案确定
            while (!stack.isEmpty() && temperatures[stack.peek()] < temperatures[i]) {
                int idx = stack.pop();
                res[idx] = i - idx;
            }
            stack.push(i);
        }
        // 剩下的下标右边没有更热的日子，res 保持 0
        return res;
    }
}
